+    pub const Linux = if (builtin.target.os.tag == .linux) struct {
+        /// Reserved for future use (e.g. Wayland wl_surface pointer).
+        /// Currently unused because GtkGLArea manages the GL context.
+        _reserved: ?*anyopaque = null,
+    } else void;
